20	/**
21	 * Maps Owner & OwnerDto using Mapstruct
22	 */
23	@Mapper(uses = PetMapper.class)
24	public interface OwnerMapper {
25	
26	    @Mapping(target = "selfLink", expression = "java(toSelfLink(owner))")
27	    @Mapping(target = "displayName", expression = "java(toDisplayName(owner))")
28	    @Mapping(target = "salutation", expression = "java(owner.getSalutation())")
29	    @Mapping(target = "initials", expression = "java(toInitials(owner))")
30	    @Mapping(target = "locality", expression = "java(toLocality(owner))")
31	    @Mapping(target = "timezone", expression = "java(toTimezone(owner))")
32	    @Mapping(target = "contactPreference", expression = "java(toContactPreference(owner))")
33	    @Mapping(target = "ageBand", expression = "java(toAgeBand(owner))")
34	    @Mapping(target = "telephoneDisplay", expression = "java(toTelephoneDisplay(owner))")
35	    @Mapping(target = "fiscalYear", expression = "java(owner.getFiscalYear())")
36	    OwnerDto toOwnerDto(Owner owner);
37	
38	    /**
39	     * Derive the owner's read-only {@code selfLink}: the canonical API path of this owner,
40	     * {@code '/api/owners/<id>'}, built from the owner's assigned id. Returns {@code null}
41	     * when the owner has no id yet, so the field is omitted from the response.
