91	    private Integer householdMemberCount;
92	
93	    @Column(name = "possible_duplicate")
94	    private boolean possibleDuplicate;
95	
96	    @Column(name = "possible_duplicate_of")
97	    private Integer possibleDuplicateOf;
98	
99	    @Column(name = "deleted")
100	    private boolean deleted;
101	
102	    @Column(name = "idempotency_key")
103	    private String idempotencyKey;
104	
105	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
106	    private Set<Pet> pets;
107	
108	    /**
109	     * Transient, write-only request flag: when {@code true}, creating this owner is allowed even if
110	     * another owner already shares the same last name and address. Never persisted or returned.
111	     */
112	    @Transient
113	    private boolean sharesHousehold;
114	
115	    public String getTitle() {
116	        return this.title;
117	    }
118	
119	    public void setTitle(String title) {
