161	    public String getCity() {
162	        return this.city;
163	    }
164	
165	    public void setCity(String city) {
166	        this.city = city;
167	    }
168	
169	    public String getPostcode() {
170	        return this.postcode;
171	    }
172	
173	    public void setPostcode(String postcode) {
174	        this.postcode = postcode;
175	    }
176	
177	    public String getTelephone() {
178	        return this.telephone;
179	    }
180	
181	    public void setTelephone(String telephone) {
182	        this.telephone = telephone;
183	    }
184	
185	    public String getEmail() {
186	        return this.email;
187	    }
188	
189	    public void setEmail(String email) {
190	        this.email = email;
191	    }
192	
193	    public LocalDate getRegistrationDate() {
194	        return this.registrationDate;
195	    }
196	
197	    public void setRegistrationDate(LocalDate registrationDate) {
198	        this.registrationDate = registrationDate;
199	    }
