201	    public LocalDate getBirthDate() {
202	        return this.birthDate;
203	    }
204	
205	    public void setBirthDate(LocalDate birthDate) {
206	        this.birthDate = birthDate;
207	    }
208	
209	    /**
210	     * Derive the owner's read-only {@code ageBand} from {@code birthDate}, computed against the
211	     * owner's {@code registrationDate} (falling back to the current date when no registration date
212	     * has been assigned yet): {@code MINOR} when under 18, {@code ADULT} from 18 to 64 inclusive,
213	     * {@code SENIOR} at 65 or older. Returns {@code null} when no {@code birthDate} has been supplied.
214	     */
215	    @Transient
216	    public String getAgeBand() {
217	        if (this.birthDate == null) {
218	            return null;
219	        }
220	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
221	        int age = Period.between(this.birthDate, reference).getYears();
222	        if (age < 18) {
223	            return "MINOR";
224	        }
225	        if (age < 65) {
226	            return "ADULT";
227	        }
228	        return "SENIOR";
229	    }
230	
