232	        return this.customerCode;
233	    }
234	
235	    public void setCustomerCode(String customerCode) {
236	        this.customerCode = customerCode;
237	    }
238	
239	    public String getMembershipNumber() {
240	        return this.membershipNumber;
241	    }
242	
243	    public void setMembershipNumber(String membershipNumber) {
244	        this.membershipNumber = membershipNumber;
245	    }
246	
247	    public String getHouseholdId() {
248	        return this.householdId;
249	    }
250	
251	    public void setHouseholdId(String householdId) {
252	        this.householdId = householdId;
253	    }
254	
255	    public Integer getNamesakeCount() {
256	        return this.namesakeCount;
257	    }
258	
259	    public void setNamesakeCount(Integer namesakeCount) {
260	        this.namesakeCount = namesakeCount;
261	    }
262	
263	    /**
264	     * Derive the owner's {@code membershipPoints}: a score starting at 0 that adds 2 when an email
265	     * is present, adds 1 when the owner's name was unique at creation time ({@code namesakeCount}
266	     * is 0), adds 2 when the owner belongs to a household of three or more members, and adds 3 when
267	     * the owner's tenure is at least one elapsed fiscal year (measured from the
268	     * {@code registrationDate} to today, where the fiscal year starts on 1 July).
269	     */
270	    @Transient
271	    public Integer getMembershipPoints() {
272	        int points = 0;
273	        if (this.email != null && !this.email.isBlank()) {
274	            points += 2;
275	        }
276	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
277	            points += 1;
278	        }
279	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
280	            points += 2;
281	        }
282	        if (hasTenureOverOneFiscalYear()) {
283	            points += 3;
284	        }
285	        return points;
286	    }
287	
288	    /**
289	     * Derive the owner's numeric {@code membershipLevel}, from 1 to 4, by mapping the owner's
290	     * {@code membershipPoints}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5
291	     * points, and level 4 for 6 or more points.
292	     */
293	    @Transient
294	    public Integer getMembershipLevel() {
295	        int points = getMembershipPoints();
296	        if (points <= 1) {
297	            return 1;
298	        }
299	        if (points <= 3) {
300	            return 2;
301	        }
302	        if (points <= 5) {
303	            return 3;
304	        }
305	        return 4;
306	    }
307	
308	    /**
309	     * Whether the owner's tenure, measured as the number of elapsed fiscal years from
310	     * {@code registrationDate} to today (the fiscal year starting on 1 July), is at least one —
311	     * worth 3 membership points. A missing {@code registrationDate} (and therefore zero tenure)
312	     * never qualifies.
313	     */
314	    @Transient
315	    private boolean hasTenureOverOneFiscalYear() {
316	        if (this.registrationDate == null) {
317	            return false;
318	        }
319	        return fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1;
320	    }
321	
322	    /**
323	     * Derive the owner's read-only {@code fiscalYear}: {@code 'FY<YY>'} where YY is the last two
324	     * digits of the fiscal year of the owner's business-day-adjusted {@code registrationDate}. The
325	     * fiscal year starts on 1 July, so a registration on or after 1 July belongs to the fiscal year
326	     * ending the following 30 June. Returns {@code null} when no {@code registrationDate} has been
327	     * assigned yet, so the field is omitted from the response.
328	     */
329	    @Transient
330	    public String getFiscalYear() {
331	        if (this.registrationDate == null) {
332	            return null;
333	        }
334	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
335	    }
336	
337	    /**
338	     * The fiscal year a {@code date} falls in, identified by its ending calendar year. The fiscal
339	     * year starts on 1 July, so dates on or after 1 July belong to the following year's fiscal year
340	     * (e.g. 1 July 2026 is fiscal year 2027), while dates from 1 January to 30 June belong to the
341	     * current year's fiscal year.
342	     */
343	    public static int fiscalYearOf(LocalDate date) {
344	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
345	    }
346	
347	    /**
348	     * Derive the owner's read-only {@code checkDigit}: a single Luhn check digit (0-9) computed
349	     * over the digits contained in the owner's {@code customerCode}. Non-digit characters (the
350	     * '-' separators and letters) are ignored. Returns {@code null} when no {@code customerCode}
351	     * has been assigned yet.
352	     */
353	    @Transient
354	    public Integer getCheckDigit() {
355	        if (this.customerCode == null) {
356	            return null;
357	        }
358	        int sum = 0;
359	        boolean dbl = true;
360	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
361	            char c = this.customerCode.charAt(i);
362	            if (c < '0' || c > '9') {
363	                continue;
364	            }
365	            int d = c - '0';
366	            if (dbl) {
